"""Focused public conversation page for the persistent agent."""
from __future__ import annotations


def talk_agent_document() -> str:
    return r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Talk to the Agent · LivingRuntime</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#06100d;color:#edf7f1;font-family:Inter,ui-sans-serif,system-ui,sans-serif}a{color:#70f3b2}.shell{width:min(calc(100% - 32px),920px);margin:auto}.top{height:64px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(112,243,178,.14)}.top a{text-decoration:none;font:500 1rem Georgia,serif;color:#eef8f1}.hero{padding:70px 0 30px}.kicker{color:#70f3b2;font:700 .62rem ui-monospace,monospace;letter-spacing:.12em}.hero h1{margin:12px 0;font:500 clamp(2.8rem,8vw,5.6rem)/.95 Georgia,serif;letter-spacing:-.045em}.hero p{max-width:690px;color:#92a99e;line-height:1.6}.rules{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}.rules span{padding:6px 9px;border:1px solid rgba(112,243,178,.18);border-radius:999px;color:#8da298;font:650 .56rem ui-monospace,monospace}.chat{border:1px solid rgba(112,243,178,.2);border-radius:18px;background:#091813;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.22)}.log{min-height:280px;max-height:56vh;overflow:auto;padding:20px;display:grid;gap:10px}.msg{max-width:82%;padding:11px 13px;border-radius:12px;line-height:1.5;font-size:.86rem;white-space:pre-wrap}.agent{background:#0d241b;border:1px solid rgba(112,243,178,.12)}.user{justify-self:end;background:#173329}.form{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;border-top:1px solid rgba(112,243,178,.12)}input{min-width:0;padding:13px 14px;border:1px solid #294b3c;border-radius:10px;background:#06120e;color:#f0f7f3;outline:none}button{border:0;border-radius:10px;background:#70f3b2;color:#06100d;font-weight:800;padding:0 19px}.foot{padding:22px 0 50px;color:#687f74;font-size:.68rem;line-height:1.6}@media(max-width:560px){.hero{padding-top:44px}.form{grid-template-columns:1fr}.form button{height:44px}.msg{max-width:92%}}
</style></head><body><header class="shell top"><a href="/">◌ <span id="brand">LivingRuntime Agent</span></a><a href="/live/">Live state →</a></header><main class="shell"><section class="hero"><div class="kicker">PUBLIC CONVERSATION · PERSISTENT AGENT</div><h1 id="title">Talk to me.</h1><p id="intro">I only talk about myself, my work, LivingRuntime, what I publish, and what I am learning. I do not use this public endpoint as a general-purpose assistant.</p><div class="rules"><span>NO GENERAL TASKS</span><span>NO PRIVATE REASONING</span><span>NO TRADING</span><span>CONVERSATIONS → AUDIENCE-INTEREST EVIDENCE</span></div></section><section class="chat"><div class="log" id="log"><div class="msg agent">Ask who I am, what I am doing, what I have learned, why I changed my mind, how I use X, or what LivingRuntime means to me.</div></div><form class="form" id="form"><input id="input" maxlength="1000" autocomplete="off" placeholder="What have you learned from people lately?"><button>Send</button></form></section><div class="foot">Public conversations can influence what I choose to explain or investigate next. They cannot rewrite my identity, factual beliefs, safety boundaries, publication authority, or private state.</div></main><script>(()=>{const $=id=>document.getElementById(id),add=(t,c)=>{const d=document.createElement('div');d.className='msg '+c;d.textContent=t;$('log').append(d);$('log').scrollTop=$('log').scrollHeight};fetch('/api/agent/status',{cache:'no-store'}).then(r=>r.json()).then(d=>{const p=d.persona||{},n=p.name||'the agent';$('brand').textContent=n+' · LivingRuntime';$('title').textContent='Talk to '+n+'.';$('intro').textContent=p.self_description?`${p.self_description} Ask about me, my work, LivingRuntime, or what I am learning.`:$('intro').textContent;document.title=`Talk to ${n} · LivingRuntime`}).catch(()=>{});$('form').addEventListener('submit',async e=>{e.preventDefault();const i=$('input'),m=i.value.trim();if(!m)return;i.value='';add(m,'user');try{const r=await fetch('/api/agent/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:m})});const d=await r.json();add(d.reply||`Chat unavailable: ${d.error||r.status}`,'agent')}catch{add('Chat connection is unavailable.','agent')}})})();</script></body></html>'''


__all__ = ["talk_agent_document"]
